python3 -c "
import glob
import pandas as pd
import json

def parse_num(val, is_european):
    if pd.isna(val): return float('nan')
    val_str = str(val).strip()
    if not val_str: return float('nan')
    if is_european:
        # European format: 18.000,0000 -> remove dot, replace comma with dot
        if ',' in val_str:
            clean = val_str.replace('.', '').replace(',', '.')
        else:
            clean = val_str
    else:
        clean = val_str.replace(',', '')
    try:
        return float(clean)
    except ValueError:
        return float('nan')

with open('/app/dataset/sensors_calibration.json') as f:
    calib = json.load(f)['enterprise_platform']['deployment_environments']['system_config']['farms']

for farm_id in sorted(calib.keys()):
    path = f'/app/dataset/production_{farm_id}.csv'
    with open(path, 'rb') as fp:
        raw = fp.read(4096)
    enc = 'utf-16' if raw.startswith(b'\xff\xfe') or raw.startswith(b'\xfe\xff') else 'utf-8'
    with open(path, 'r', encoding=enc, errors='ignore') as fp:
        lines = [fp.readline() for _ in range(5)]
    sep = ';' if ';' in lines[3] else ','
    val_col = calib[farm_id]['calibration_data']['value_column_name']
    df = pd.read_csv(path, skiprows=3, sep=sep, encoding=enc)

    parsed = df[val_col].apply(lambda x: parse_num(x, sep == ';'))
    nan_count = parsed.isna().sum()
    print(f'{farm_id:6s} | total: {len(df):3d} | parsed_valid: {len(df) - nan_count:3d} | nan: {nan_count:2d}')
"
